DO $$ DECLARE n int; BEGIN SELECT count(*) INTO n FROM public.profiles WHERE email LIKE 'sahne+%'; IF n <> 171 THEN RAISE EXCEPTION 'profil sayisi % (beklenen 171) — handle_new_user?', n; END IF; END $$;

-- Sahne yoneticisi (admin paneli icin); koruma tetikleyicisi gecici kapatilir (asama4 T5 kalibi)

ALTER TABLE public.profiles DISABLE TRIGGER protect_profile_fields;
UPDATE public.profiles SET is_admin = true WHERE id = '5a4e0000-0000-4000-8000-000000090001';
ALTER TABLE public.profiles ENABLE TRIGGER protect_profile_fields;

-- profil alanlari (onay alanlari icin auth.uid() = Sahne yoneticisi)

DO $$
BEGIN
  PERFORM set_config('request.jwt.claim.sub', '5a4e0000-0000-4000-8000-000000090001', true);
  UPDATE public.profiles p SET
    slug = v.slug, bio = v.bio, city_id = pg_temp.sehir(v.sehir), primary_category_id = pg_temp.kat(v.kat),
    attributes = v.attrs, category_attributes = v.cat_attrs, approval_status = v.onay::public.profile_approval_status,
    approved_at = v.onay_at, approval_note = v.onay_not, suspended_at = v.askida_at, suspension_reason = v.askida_neden,
    suspended_by = CASE WHEN v.askida_at IS NULL THEN NULL ELSE '5a4e0000-0000-4000-8000-000000090001'::uuid END,
    is_published = v.yayinda, premium_tier = v.premium::public.premium_tier, premium_until = v.premium_until,
    last_seen_at = v.son_gorulme, created_at = v.kayit, welcome_email_sent_at = v.kayit
  FROM (VALUES
('5a4e0000-0000-4000-8000-000000010001', 'eda-bozkurt', 'Düğün ve kurumsal etkinlik fotoğrafçılığında 3 yıllık deneyim. İzmir ve çevre illerde çalışıyorum; düğün ve aile ağırlıklı portföyüm var. İkinci fotoğrafçı ve drone desteği sağlayabilirim.', 'İzmir', 'fotografci', '{"shoot_types": ["portrait", "newborn", "wedding", "product"], "style": ["vintage", "minimal", "artistic", "classic"], "extras": ["studio", "drone", "makeup", "album"], "delivery_format": ["digital", "album", "print", "online"], "team_type": "both", "delivery_time": "normal", "experience": "mid"}'::jsonb, '{"etkinlik_turleri": ["launch", "wedding", "corporate"]}'::jsonb, 'approved', pg_temp.t(7390.82), NULL, NULL, NULL, true, 'premium', pg_temp.t(-1680.00), pg_temp.t(115.55), pg_temp.t(7425.21)),
('5a4e0000-0000-4000-8000-000000010002', 'berk-polat', 'Düğün ve kurumsal etkinlik fotoğrafçılığında 9 yıllık deneyim. Muğla ve çevre illerde çalışıyorum; lansman ve gala ağırlıklı portföyüm var. İkinci fotoğrafçı ve drone desteği sağlayabilirim.', 'Muğla', 'fotografci', '{"shoot_types": ["corporate", "event"], "style": ["vintage", "classic", "artistic", "minimal"], "extras": ["studio", "video", "drone", "makeup"], "delivery_format": ["album", "online", "print", "digital"], "team_type": "team", "delivery_time": "fast", "experience": "senior"}'::jsonb, '{"etkinlik_turleri": ["wedding", "corporate", "other", "launch"]}'::jsonb, 'approved', pg_temp.t(3236.35), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(479.84), pg_temp.t(3293.15)),
('5a4e0000-0000-4000-8000-000000010003', 'kerem-oz', 'Düğün ve kurumsal etkinlik fotoğrafçılığında 10 yıllık deneyim. İstanbul ve çevre illerde çalışıyorum; lansman ve gala ağırlıklı portföyüm var. İkinci fotoğrafçı ve drone desteği sağlayabilirim.', 'İstanbul', 'fotografci', '{"shoot_types": ["food"], "style": ["classic", "documentary"], "extras": ["second", "makeup", "album", "video"], "delivery_format": ["digital", "online", "album", "print"], "team_type": "solo", "delivery_time": "normal", "experience": "expert"}'::jsonb, '{"etkinlik_turleri": ["henna", "wedding", "launch"]}'::jsonb, 'approved', pg_temp.t(2426.92), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(407.02), pg_temp.t(2444.47)),
('5a4e0000-0000-4000-8000-000000010004', 'burcu-ates', 'Düğün ve kurumsal etkinlik fotoğrafçılığında 12 yıllık deneyim. İstanbul ve çevre illerde çalışıyorum; düğün ve aile ağırlıklı portföyüm var. İkinci fotoğrafçı ve drone desteği sağlayabilirim.', 'İstanbul', 'fotografci', '{"shoot_types": ["wedding", "event", "architecture", "fashion"], "style": ["minimal", "documentary", "artistic"], "extras": ["sameday", "album"], "delivery_format": ["album", "digital", "online"], "team_type": "team", "delivery_time": "fast", "experience": "expert"}'::jsonb, '{"etkinlik_turleri": ["wedding", "henna", "engagement"]}'::jsonb, 'approved', pg_temp.t(6879.89), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(440.08), pg_temp.t(6917.83)),
('5a4e0000-0000-4000-8000-000000010005', 'tugce-duman', 'Düğün ve kurumsal etkinlik fotoğrafçılığında 9 yıllık deneyim. Eskişehir ve çevre illerde çalışıyorum; düğün ve nişan ağırlıklı portföyüm var. İkinci fotoğrafçı ve drone desteği sağlayabilirim.', 'Eskişehir', 'fotografci', '{"shoot_types": ["portrait"], "style": ["documentary", "minimal", "vintage"], "extras": ["sameday", "makeup", "video"], "delivery_format": ["online", "digital"], "team_type": "team", "delivery_time": "fast", "experience": "senior"}'::jsonb, '{"etkinlik_turleri": ["engagement", "henna", "launch"]}'::jsonb, 'approved', pg_temp.t(3455.95), NULL, NULL, NULL, true, 'premium', pg_temp.t(-5760.00), pg_temp.t(344.45), pg_temp.t(3468.18)),
('5a4e0000-0000-4000-8000-000000010006', 'busra-sezer', '3 yıldır Adana merkezli çalışan bir etkinlik fotoğrafçısıyım. lansman ve gala çekimlerinde doğal ışık ve anı yakalamaya odaklanırım. Teslimatı 10 gün içinde online galeriyle yaparım.', 'Adana', 'fotografci', '{"shoot_types": ["food", "event", "family", "sports"], "style": ["artistic", "classic", "minimal", "vintage"], "extras": ["album", "drone"], "delivery_format": ["online", "digital"], "team_type": "both", "delivery_time": "standard", "experience": "mid"}'::jsonb, '{"etkinlik_turleri": ["engagement", "birthday", "wedding", "corporate", "launch"]}'::jsonb, 'approved', pg_temp.t(9446.20), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(321.65), pg_temp.t(9465.77)),
('5a4e0000-0000-4000-8000-000000010007', 'tuba-bozkurt', 'Düğün ve kurumsal etkinlik fotoğrafçılığında 8 yıllık deneyim. Antalya ve çevre illerde çalışıyorum; düğün ve aile ağırlıklı portföyüm var. İkinci fotoğrafçı ve drone desteği sağlayabilirim.', 'Antalya', 'fotografci', '{"shoot_types": ["newborn", "product", "food", "architecture"], "style": ["vintage", "documentary", "artistic", "minimal"], "extras": ["studio"], "delivery_format": ["digital", "online"], "team_type": "team", "delivery_time": "fast", "experience": "senior"}'::jsonb, '{"etkinlik_turleri": ["wedding", "engagement", "birthday", "corporate", "henna"]}'::jsonb, 'approved', pg_temp.t(790.75), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(173.09), pg_temp.t(833.55)),
('5a4e0000-0000-4000-8000-000000010008', 'bahar-yalcin', '9 yıldır Ankara merkezli çalışan bir etkinlik fotoğrafçısıyım. düğün ve nişan çekimlerinde doğal ışık ve anı yakalamaya odaklanırım. Teslimatı 10 gün içinde online galeriyle yaparım.', 'Ankara', 'fotografci', '{"shoot_types": ["architecture", "family", "event"], "style": ["artistic", "documentary", "vintage"], "extras": ["album", "makeup"], "delivery_format": ["digital", "online"], "team_type": "team", "delivery_time": "standard", "experience": "senior"}'::jsonb, '{"etkinlik_turleri": ["engagement", "corporate", "wedding"]}'::jsonb, 'approved', pg_temp.t(4566.55), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(331.04), pg_temp.t(4595.88)),
('5a4e0000-0000-4000-8000-000000010009', 'oguz-ozdemir', '4 yıldır Ankara merkezli çalışan bir etkinlik fotoğrafçısıyım. lansman ve gala çekimlerinde doğal ışık ve anı yakalamaya odaklanırım. Teslimatı 1 hafta içinde online galeriyle yaparım.', 'Ankara', 'fotografci', '{"shoot_types": ["food", "portrait", "family", "corporate"], "style": ["artistic", "documentary"], "extras": ["drone"], "delivery_format": ["album", "print", "online"], "team_type": "solo", "delivery_time": "fast", "experience": "mid"}'::jsonb, '{"etkinlik_turleri": ["baby_shower", "birthday", "engagement"]}'::jsonb, 'approved', pg_temp.t(8654.48), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(93.80), pg_temp.t(8658.23)),
('5a4e0000-0000-4000-8000-000000010010', 'deniz-unal', 'Düğün ve kurumsal etkinlik fotoğrafçılığında 3 yıllık deneyim. Eskişehir ve çevre illerde çalışıyorum; lansman ve gala ağırlıklı portföyüm var. İkinci fotoğrafçı ve drone desteği sağlayabilirim.', 'Eskişehir', 'fotografci', '{"shoot_types": ["social", "sports", "product", "corporate"], "style": ["artistic"], "extras": ["video", "sameday", "makeup"], "delivery_format": ["online"], "team_type": "team", "delivery_time": "standard", "experience": "mid"}'::jsonb, '{"etkinlik_turleri": ["concert", "wedding", "baby_shower", "corporate", "engagement"]}'::jsonb, 'approved', pg_temp.t(2148.85), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(74.71), pg_temp.t(2198.82)),
('5a4e0000-0000-4000-8000-000000010011', 'yusuf-duman', 'Pistin boş kalmadığı etkinlikler için çalışıyorum. 9 yıllık sahne deneyimi, latin ve pop repertuvarı ve MC desteği. Bursa ve Türkiye genelinde seyahat ederim.', 'Bursa', 'dj', '{"music_style": ["pop", "retro"], "event_types": ["club", "corporate", "festival"], "extras": ["fog"], "language": ["foreign", "mixed", "tr"], "team_type": "team", "experience": "senior"}'::jsonb, '{"etkinlik_turleri": ["henna", "wedding", "birthday"]}'::jsonb, 'approved', pg_temp.t(3385.33), NULL, NULL, NULL, false, 'none', NULL, pg_temp.t(200.83), pg_temp.t(3448.63)),
('5a4e0000-0000-4000-8000-000000010012', 'merve-avci', 'İstanbul merkezli DJ. 8 yıldır düğün, nişan ve kurumsal etkinliklerde set yapıyorum; pop ve elektronik tarzında dinleyiciyi okuyan bir akış kurarım. Kendi ses ve ışık sistemimle gelebilirim.', 'İstanbul', 'dj', '{"music_style": ["pop", "electronic", "retro", "jazz"], "event_types": ["birthday", "corporate", "club", "wedding"], "extras": ["fog", "live"], "language": ["tr"], "team_type": "solo", "experience": "senior"}'::jsonb, '{"etkinlik_turleri": ["birthday", "engagement", "gala", "wedding", "launch"]}'::jsonb, 'approved', pg_temp.t(10529.29), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(426.19), pg_temp.t(10596.55)),
('5a4e0000-0000-4000-8000-000000010013', 'naz-guler', 'İstanbul merkezli DJ. 2 yıldır düğün, nişan ve kurumsal etkinliklerde set yapıyorum; karma tarzında dinleyiciyi okuyan bir akış kurarım. Kendi ses ve ışık sistemimle gelebilirim.', 'İstanbul', 'dj', '{"music_style": ["hiphop", "pop", "retro"], "event_types": ["corporate", "engagement", "wedding"], "extras": ["sound", "lighting", "mc"], "language": ["foreign", "mixed", "tr"], "team_type": "team", "experience": "mid"}'::jsonb, '{"etkinlik_turleri": ["gala", "wedding", "engagement", "corporate", "birthday"]}'::jsonb, 'approved', pg_temp.t(6165.48), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(274.59), pg_temp.t(6229.72)),
