('5a4e0000-0000-4000-8000-000000010120', 'merve-yalcin', 'Havadan görüntüyle etkinliğin ölçeğini gösteririm. 3 yıl deneyim, düğün ve dış çekim ağırlıklı; FPV ve sinema drone seçenekleri. Antalya ve çevre iller.', 'Antalya', 'drone-pilotu', '{}'::jsonb, '{"service_region": "Şehir dışına çıkar", "experience_label": "3 yıl · 90+ etkinlik", "calisma_sekli": "Ajansa bağlı", "quick": {"drone_tipi": ["FPV drone"], "lokasyon_tipi": ["Kentsel"], "teslim_bicimi": "Fotoğraf", "teslim_suresi": "1 ay+"}, "logistics": {"ucus_izni": true, "kendi_ekipmani": true}, "modules": {"ekipman": {"items": ["DJI Mavic 3 Pro", "DJI Avata 2 (FPV)", "Yedek batarya x6", "ND filtre seti"], "venue_requirements": "Sahne yakınında 2 adet 16A priz, kurulum için 60 dk."}, "teknik_teslimat": {"delivery": {"Teslim süresi": "1 ay+", "Format": "4K + 1080p", "Yedekleme": "Çift kart + bulut"}}, "uzmanlik_alanlari": {"areas": ["Spor / Aksiyon Çekimi", "Drone Fotoğrafçısı", "Kurumsal Tesis Çekimi", "Tanıtım Filmi Hava Çekimi"]}, "calisma_parametreleri": {"params": {"Minimum süre": "Tam gün", "Şehir dışı": "Ulaşım + konaklama müşteriye ait", "Ödeme": "%30 kapora, kalan etkinlik günü"}, "notes": "Hafta sonu ve resmi tatil için önceden rezervasyon önerilir."}}, "etkinlik_turleri": ["corporate", "launch", "concert"]}'::jsonb, 'approved', pg_temp.t(7506.72), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(472.87), pg_temp.t(7550.53)),
('5a4e0000-0000-4000-8000-000000010121', 'fatih-keskin', 'Havadan görüntüyle etkinliğin ölçeğini gösteririm. 7 yıl deneyim, kurumsal tesis ağırlıklı; FPV ve sinema drone seçenekleri. Ankara ve çevre iller.', 'Ankara', 'drone-pilotu', '{}'::jsonb, '{"service_region": "Yalnızca kendi şehri", "experience_label": "7 yıl · 273+ etkinlik", "calisma_sekli": "Ajansa bağlı", "quick": {"drone_tipi": ["FPV drone", "Standart drone", "Mini drone"], "lokasyon_tipi": ["Açık alan", "Dağ ve orman"], "teslim_bicimi": "Fotoğraf", "teslim_suresi": "1 ay+"}, "logistics": {"kurgu_dahil": true}, "modules": {"ekipman": {"items": ["DJI Mavic 3 Pro", "DJI Avata 2 (FPV)", "Yedek batarya x6", "ND filtre seti"], "venue_requirements": "Sahne yakınında 2 adet 16A priz, kurulum için 60 dk."}, "teknik_teslimat": {"delivery": {"Teslim süresi": "1 ay+", "Format": "4K + 1080p", "Yedekleme": "Çift kart + bulut"}}, "uzmanlik_alanlari": {"areas": ["Kurumsal Tesis Çekimi", "Outdoor Etkinlik Çekimi", "Drone Fotoğrafçısı", "Spor / Aksiyon Çekimi"]}, "calisma_parametreleri": {"params": {"Minimum süre": "2 saat", "Şehir dışı": "Ulaşım + konaklama müşteriye ait", "Ödeme": "%30 kapora, kalan etkinlik günü"}, "notes": "Hafta sonu ve resmi tatil için önceden rezervasyon önerilir."}}, "etkinlik_turleri": ["concert", "wedding", "other"]}'::jsonb, 'approved', pg_temp.t(5848.48), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(46.72), pg_temp.t(5898.41)),
('5a4e0000-0000-4000-8000-000000010122', 'selim-dogan', 'Havadan görüntüyle etkinliğin ölçeğini gösteririm. 7 yıl deneyim, konser ve festival ağırlıklı; FPV ve sinema drone seçenekleri. Trabzon ve çevre iller.', 'Trabzon', 'drone-pilotu', '{}'::jsonb, '{"service_region": "Türkiye geneli + çevrimiçi", "experience_label": "7 yıl · 266+ etkinlik", "calisma_sekli": "Ajansa bağlı", "quick": {"drone_tipi": ["Standart drone", "Sinema drone", "FPV drone"], "lokasyon_tipi": ["Açık alan", "Dağ ve orman"], "teslim_bicimi": "Video + Fotoğraf", "teslim_suresi": "1 ay+"}, "logistics": {"kendi_ekipmani": true}, "modules": {"ekipman": {"items": ["DJI Mavic 3 Pro", "DJI Avata 2 (FPV)", "Yedek batarya x6", "ND filtre seti"], "venue_requirements": "Sahne yakınında 2 adet 16A priz, kurulum için 60 dk."}, "teknik_teslimat": {"delivery": {"Teslim süresi": "1 ay+", "Format": "Online galeri + USB", "Yedekleme": "Çift kart + bulut"}}, "uzmanlik_alanlari": {"areas": ["Spor / Aksiyon Çekimi", "Drone Fotoğrafçısı", "Kurumsal Tesis Çekimi", "FPV Drone Pilotu"]}, "calisma_parametreleri": {"params": {"Minimum süre": "Yarım gün", "Şehir dışı": "Ulaşım + konaklama müşteriye ait", "Ödeme": "%30 kapora, kalan etkinlik günü"}, "notes": "Hafta sonu ve resmi tatil için önceden rezervasyon önerilir."}}, "etkinlik_turleri": ["other", "corporate", "wedding", "launch"]}'::jsonb, 'approved', pg_temp.t(7425.64), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(218.76), pg_temp.t(7437.59)),
('5a4e0000-0000-4000-8000-000000020001', 'ajans-nova', 'Nova Etkinlik, 2014''ten beri İstanbul''da düğün, nişan ve kurumsal etkinlik organizasyonu yapan tam kapsamlı bir ajanstır. Konsept tasarımı, tedarikçi yönetimi ve etkinlik günü operasyonunu tek ekipten yürütür; 60''ın üzerinde düzenli freelance iş ortağıyla çalışır.', 'İstanbul', 'organizasyon', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "6 yıl · 360+ etkinlik", "etkinlik_turleri": ["launch", "wedding", "fair", "conference", "engagement"]}'::jsonb, 'approved', pg_temp.t(5325.19), NULL, NULL, NULL, true, 'agency', pg_temp.t(-4632.00), pg_temp.t(8.97), pg_temp.t(5342.69)),
('5a4e0000-0000-4000-8000-000000020002', 'ajans-lumen', 'Lumen Prodüksiyon konser, konferans ve lansmanlarda ses, ışık, LED ekran ve canlı yayın altyapısını kurar. 2.000 kişiye kadar sahne çözümleri, çok kameralı reji ve hibrit yayın hizmetini kendi ekipmanıyla sunar.', 'İstanbul', 'ses-isik', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "6 yıl · 360+ etkinlik", "etkinlik_turleri": ["corporate", "launch", "concert", "conference", "wedding", "fair"]}'::jsonb, 'approved', pg_temp.t(5161.86), NULL, NULL, NULL, true, 'plus', pg_temp.t(-7128.00), pg_temp.t(26.44), pg_temp.t(5181.47)),
('5a4e0000-0000-4000-8000-000000020003', 'ajans-atlas', 'Ankara merkezli Atlas Organizasyon, kamu ve özel sektör için kongre, bayi toplantısı ve protokol etkinlikleri düzenler. Kayıt sistemi, simultane çeviri ve sahne prodüksiyonu dahil anahtar teslim çözüm sunar.', 'Ankara', 'organizasyon', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "8 yıl · 480+ etkinlik", "etkinlik_turleri": ["congress", "gala", "corporate", "launch"]}'::jsonb, 'approved', pg_temp.t(5464.62), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(26.55), pg_temp.t(5481.34)),
('5a4e0000-0000-4000-8000-000000020004', 'ajans-kuzey-yildizi', 'İzmir ve Ege kıyılarında butik düğün ve kına organizasyonları. Kuzey Yıldızı Events, Çeşme, Alaçatı ve Urla''daki mekan ağıyla açık hava davetleri planlar; dekorasyon ve çiçek tasarımı ekibi kendisine aittir.', 'İzmir', 'organizasyon', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "6 yıl · 360+ etkinlik", "etkinlik_turleri": ["corporate", "baby_shower", "birthday", "wedding"]}'::jsonb, 'approved', pg_temp.t(7550.33), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(144.48), pg_temp.t(7566.14)),
('5a4e0000-0000-4000-8000-000000020005', 'ajans-mavi-sahne', 'Mavi Sahne, sahne sanatçıları temsil eden bir müzik ve performans ajansıdır. Orkestra, DJ, dans ve akrobasi ekipleriyle düğün, gala ve festival programlarına sanatçı sağlar; ses ve ışık ortaklarıyla paket teklif verir.', 'İstanbul', 'muzisyen', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "10 yıl · 600+ etkinlik", "etkinlik_turleri": ["wedding", "corporate", "gala", "launch", "concert", "conference"]}'::jsonb, 'approved', pg_temp.t(7925.66), NULL, NULL, NULL, true, 'agency', pg_temp.t(-6192.00), pg_temp.t(32.41), pg_temp.t(7976.45)),
('5a4e0000-0000-4000-8000-000000020006', 'ajans-arti-bir', 'Artı Bir Ajans sunucu, konuşmacı ve komedyen portföyüyle kurumsal etkinliklerin sahne akışını kurar. Bayi toplantısı, ödül töreni ve lansmanlar için iki dilli sunucu ve ara performans sağlar.', 'İstanbul', 'sunucu', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "8 yıl · 480+ etkinlik", "etkinlik_turleri": ["corporate", "launch", "conference", "gala"]}'::jsonb, 'approved', pg_temp.t(10605.20), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(27.76), pg_temp.t(10651.30)),
('5a4e0000-0000-4000-8000-000000020007', 'ajans-ritim', 'Antalya merkezli Ritim Müzik Ajansı otel ve beach club etkinliklerine DJ, canlı müzik ve dans ekipleri sağlar. Sezonluk rezidans programları ve düğün paketleriyle Akdeniz bölgesinde çalışır.', 'Antalya', 'dj', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "14 yıl · 840+ etkinlik", "etkinlik_turleri": ["corporate", "launch", "wedding", "birthday", "gala", "engagement"]}'::jsonb, 'approved', pg_temp.t(9379.62), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(117.60), pg_temp.t(9412.34)),
('5a4e0000-0000-4000-8000-000000020008', 'ajans-vizyon-cast', 'Vizyon Cast Ajansı reklam, katalog ve etkinlikler için model, oyuncu ve host kadrosu sağlar. 200''ü aşkın portföy, seçme (casting) organizasyonu ve set günü koordinasyonu hizmetleriyle marka ve prodüksiyon şirketleriyle çalışır.', 'İstanbul', 'model', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "12 yıl · 720+ etkinlik", "etkinlik_turleri": ["launch", "other", "corporate", "fair", "gala"]}'::jsonb, 'approved', pg_temp.t(4741.18), NULL, NULL, NULL, true, 'plus', pg_temp.t(-5400.00), pg_temp.t(86.62), pg_temp.t(4770.60)),
('5a4e0000-0000-4000-8000-000000020009', 'ajans-pusula', 'Bursa merkezli Pusula Etkinlik sanayi kuruluşlarının bayi toplantısı, fabrika açılışı ve fuar katılımlarını planlar. Saha koordinasyon ekibi, hostes kadrosu ve teknik tedarikçi ağıyla Marmara bölgesinde hizmet verir.', 'Bursa', 'etkinlik-koordinatoru', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "10 yıl · 600+ etkinlik", "etkinlik_turleri": ["launch", "wedding", "corporate", "conference", "baby_shower"]}'::jsonb, 'approved', pg_temp.t(9238.99), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(34.11), pg_temp.t(9266.00)),
('5a4e0000-0000-4000-8000-000000020010', 'ajans-ekim', 'Ekim Kreatif, lansman ve marka etkinliklerinin sosyal medya katmanını yönetir: içerik üreticisi eşleştirme, etkinlik günü çekim ekibi, canlı yayın ve aynı gün kurgu. Veriye dayalı raporlama sunar.', 'İstanbul', 'influencer', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "14 yıl · 840+ etkinlik", "etkinlik_turleri": ["fair", "corporate", "engagement", "launch"]}'::jsonb, 'approved', pg_temp.t(11588.87), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(61.60), pg_temp.t(11640.12)),
('5a4e0000-0000-4000-8000-000000020011', 'ajans-beyaz-guvercin', 'Gaziantep ve Güneydoğu''da düğün, kına ve sünnet organizasyonları. Beyaz Güvercin, yöresel müzik ekipleri, geleneksel kına programı ve çocuk eğlencesi dahil aile etkinliklerinde 12 yıllık deneyime sahiptir.', 'Gaziantep', 'organizasyon', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "10 yıl · 600+ etkinlik", "etkinlik_turleri": ["concert", "wedding", "henna", "engagement", "birthday"]}'::jsonb, 'approved', pg_temp.t(2409.03), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(55.00), pg_temp.t(2456.08)),
('5a4e0000-0000-4000-8000-000000020012', 'ajans-zirve', 'Zirve Teknik Prodüksiyon kongre ve konferanslara simultane çeviri kabini, ses-ışık, kayıt ve canlı yayın altyapısı sağlar. Ankara''daki kongre merkezlerinde düzenli tedarikçidir; 1.500 kişiye kadar salon kurulumu yapar.', 'Ankara', 'ses-isik', '{}'::jsonb, '{"service_region": "Türkiye geneli", "experience_label": "6 yıl · 360+ etkinlik", "etkinlik_turleri": ["wedding", "corporate", "conference", "concert"]}'::jsonb, 'approved', pg_temp.t(8046.91), NULL, NULL, NULL, true, 'none', NULL, pg_temp.t(227.66), pg_temp.t(8058.42)),
